/// The bytes of a `CHAR` array after `strcpy` of `written`, or with no copy.
fn expected_array<const N: usize>(written: Option<&str>) -> [u8; N] {
    let mut out = [0xAA; N];
    if let Some(text) = written {
        out[..text.len()].copy_from_slice(text.as_bytes());
        out[text.len()] = 0;
    }
    out
}

#[test]
fn oracle_rows_match_wine() {
    for row in ROWS {
        let mut info = row.dw_size.map(|dw_size| RasDevInfoA {
            dw_size,
            device_type: [0xAA; RAS_MAX_DEVICE_TYPE + 1],
            device_name: [0xAA; RAS_MAX_DEVICE_NAME + 1],
        });
        let mut cb = row.cb;
        let mut devices = row.devices;

        let ret = ras_enum_devices_a(info.as_mut(), cb.as_mut(), devices.as_mut());

        assert_eq!(ret, row.ret, "{} return", row.id);
        assert_eq!(cb, row.cb_out, "{} lpcb", row.id);
        assert_eq!(devices, row.devices_out, "{} lpcDevices", row.id);
        if let Some(info) = info {
            let want_type: [u8; RAS_MAX_DEVICE_TYPE + 1] = expected_array(row.device.map(|d| d.0));
            let want_name: [u8; RAS_MAX_DEVICE_NAME + 1] = expected_array(row.device.map(|d| d.1));
            assert_eq!(info.device_type, want_type, "{} device type", row.id);
            assert_eq!(info.device_name, want_name, "{} device name", row.id);
        }
    }
}
